algorithms.pseudocode:
Algorithm MinkowskiSum(A, B):
  Input: Finite sets A, B in Z^2
  Output: A + B = {a + b : a in A, b in B}
  S := empty set
  for a in A:
    for b in B:
      S := S union {(a1+b1, a2+b2)}
  return S

Algorithm MixedLatticeIndex(A, B):
  Input: Finite sets A, B in Z^2
  Output: |A+B| - |A| - |B| + 1
  S := MinkowskiSum(A, B)
  return |S| - |A| - |B| + 1
